@Column(name="title", nullable=false, length=50, unique=true)
String title;
// test 1: title=null -> blad NOT NULL
// test 2: title zbyt dlugi -> blad length
// test 3: duplikat title -> blad unique

static String toSlug(String title) {
    return title.toLowerCase().replace(" ", "-");
}
movie.setId(toSlug("Pan Tadeusz")); // "pan-tadeusz"
session.persist(movie);

long start = System.nanoTime();
for (int i = 0; i < 100; i++) session.persist(new Movie("Film " + i, 2000 + i));
long time = System.nanoTime() - start;
System.out.println("Czas: " + time + "ns");

List<Movie> all = session.createQuery("from Movie", Movie.class).getResultList();
all.forEach(m -> System.out.println(m.getTitle()));
