class User {
    @Id @GeneratedValue Long id;
    @Column(nullable=false, unique=true) String email;
    @Column(nullable=false) String username;
}

@Entity(name="Movie") @Table(name="movie")
class Movie {
    @Id @GeneratedValue Long id;
    @Column(name="title", nullable=false, length=200, unique=true) String title;
    @Column(name="release_year") int year;
    @jakarta.persistence.Transient double popularityScore;
}
// raport: title NOT NULL bo kazdy film musi miec tytul, UNIQUE bo katalog nie duplikuje tytulow, popularityScore @Transient bo liczony w runtime
